<script setup lang="ts">
import {ref,watch} from 'vue'
import type {Row} from '../types'
import UiIcon from '../components/UiIcon.vue'

const props=defineProps<{me:Row,busy:boolean,error:string,token:string}>()
const emit=defineEmits<{generateToken:[],addMember:[body:{username:string,password:string,role:string}]}>()
const memberName=ref(''),memberPassword=ref(''),memberRole=ref('ANALYST'),submitted=ref(false),created=ref(false),copied=ref(false),copyFailed=ref(false)
const roles:Record<string,string>={ADMIN:'管理员',ANALYST:'研究员',REVIEWER:'复核员'}
watch(()=>props.busy,(busy,wasBusy)=>{if(wasBusy&&!busy&&submitted.value){if(!props.error){memberName.value='';memberPassword.value='';created.value=true}submitted.value=false}})
watch(()=>props.token,()=>{copied.value=false;copyFailed.value=false})
function addMember(){submitted.value=true;created.value=false;emit('addMember',{username:memberName.value.trim(),password:memberPassword.value,role:memberRole.value})}
async function copyToken(){try{await navigator.clipboard.writeText(props.token);copied.value=true;copyFailed.value=false}catch{copyFailed.value=true}}
</script>

<template>
  <div class="settings-view">
    <section class="access-panel" aria-labelledby="api-access-heading"><div class="settings-heading"><span class="settings-icon"><UiIcon name="lock" :size="20"/></span><div><h2 id="api-access-heading">批处理 API 接入</h2></div></div><p class="section-description">将年度财报核验接入你的研究流程。令牌可提交任务及读取本账号授权的数据。</p><dl class="token-properties"><div><dt>令牌权限</dt><dd><code>submit</code><span>提交、读取与管理本人任务</span></dd></div><div><dt>有效期</dt><dd>7 天</dd></div><div><dt>人工复核</dt><dd>需使用浏览器会话完成</dd></div></dl><div class="token-actions"><button @click="emit('generateToken')" :disabled="busy"><UiIcon name="plus" :size="16"/>生成 7 天令牌</button><span>请将令牌视为账号凭证保管</span></div><div v-if="token" class="token-result"><div class="token-result-heading"><strong>仅本次显示，请及时保存</strong><button @click="copyToken">{{copied?'已复制':'复制令牌'}}</button></div><code class="token" tabindex="0" aria-label="新生成的 API 令牌">{{token}}</code><p v-if="copyFailed" class="copy-failed" role="status">复制不可用，请选中上方令牌手动复制。</p><p v-else role="status">{{copied?'令牌已复制到剪贴板。':'离开当前会话后，将无法再次查看这枚令牌。'}}</p></div></section>
    <section class="member-panel" aria-labelledby="member-heading"><div class="settings-heading"><span class="settings-icon"><UiIcon name="settings" :size="20"/></span><div><h2 id="member-heading">组织成员</h2></div></div><div class="current-member"><span class="member-avatar" aria-hidden="true">{{String(me.username||'F').slice(0,1).toUpperCase()}}</span><div><strong>{{me.username}}</strong><span>当前账号</span></div><span class="member-role">{{roles[me.role]||me.role}}</span></div><form v-if="me.role==='ADMIN'" @submit.prevent="addMember" :aria-busy="busy"><h3>新增组织成员</h3><p class="form-description">为研究员或复核员分配账号，明确各自的工作权限。</p><label for="member-username">用户名</label><input id="member-username" v-model="memberName" name="member-username" autocomplete="off" required :disabled="busy" spellcheck="false" autocapitalize="none"><label for="member-password">初始密码</label><input id="member-password" v-model="memberPassword" name="member-password" type="password" autocomplete="new-password" minlength="12" required :disabled="busy" aria-describedby="member-password-hint"><small id="member-password-hint" class="field-hint">至少 12 个字符</small><label for="member-role">角色</label><select id="member-role" v-model="memberRole" :disabled="busy"><option value="ANALYST">研究员 · 提交与跟踪任务</option><option value="REVIEWER">复核员 · 查看证据与人工复核</option><option value="ADMIN">管理员 · 团队与工作空间管理</option></select><p v-if="created" class="member-success" role="status"><UiIcon name="check" :size="16"/>成员已创建，初始密码已清空。</p><button class="primary create-member" :disabled="busy">{{busy&&submitted?'正在创建…':'创建成员'}}</button></form><p v-else class="member-permissions"><UiIcon name="lock" :size="15"/><span>组织成员由管理员统一管理。需要新增或调整成员时，请联系组织管理员。</span></p></section>
  </div>
</template>

<style scoped>
.settings-view{display:grid;grid-template-columns:minmax(0,1fr) minmax(0,1fr);gap:24px;max-width:1180px;align-items:start}.access-panel,.member-panel{min-width:0;padding:27px;background:var(--surface);border:1px solid var(--line);border-radius:8px}.settings-heading{display:flex;align-items:center;gap:13px;margin-bottom:21px}.settings-icon{width:42px;height:42px;display:grid;place-items:center;border:1px solid #dce4ef;border-radius:7px;background:#f3f6fa;color:var(--primary);flex-shrink:0}.settings-heading h2{font-size:16px;line-height:1.5;font-weight:650;margin:0}.section-description{font-size:14px;line-height:1.95;color:var(--muted);margin:0 0 25px}.token-properties{display:block;padding:0;margin:0}.token-properties>div{display:grid;grid-template-columns:81px minmax(0,1fr);gap:15px;padding:16px 0;border-top:1px solid var(--line);font-size:14px;line-height:1.9}.token-properties dt{color:var(--muted)}.token-properties dd{margin:0;color:var(--ink)}.token-properties code{padding:3px 7px;border:1px solid #dce5f2;border-radius:3px;background:#f1f5fb;color:var(--primary);font-size:12px}.token-properties dd>span{display:block;font-size:12px;color:var(--muted);margin-top:6px}.token-actions{display:flex;flex-wrap:wrap;align-items:center;gap:12px;margin-top:24px}.token-actions button{display:flex;align-items:center;gap:7px;color:var(--primary);font-size:14px;min-height:42px}.token-actions>span{font-size:12px;line-height:1.8;color:var(--muted)}.token-result{margin-top:23px;border:1px solid #cbd9ed;border-radius:6px;background:#f6f9fd;padding:15px}.token-result-heading{display:flex;align-items:center;justify-content:space-between;gap:12px;margin-bottom:12px}.token-result-heading strong{font-size:14px;color:var(--primary);font-weight:600;line-height:1.7}.token-result-heading button{font-size:12px;padding:6px 8px;min-height:44px;color:var(--primary);flex-shrink:0}.token{display:block;white-space:pre-wrap;overflow-wrap:anywhere;word-break:break-all;font-family:Consolas,"SFMono-Regular",monospace;font-size:14px;line-height:1.9;color:var(--ink);padding:11px;background:var(--surface);border:1px solid #dce4ef;border-radius:4px;user-select:all;margin:0}.token-result>p{font-size:12px;line-height:1.9;color:var(--muted);margin:11px 0 0}.token-result>p.copy-failed{color:var(--warning)}.current-member{display:flex;align-items:center;gap:11px;padding:16px 0 22px;border-bottom:1px solid var(--line)}.member-avatar{width:35px;height:35px;border:1px solid #dce5ef;border-radius:7px;display:grid;place-items:center;background:#f4f7fb;color:var(--primary);font-size:14px;font-weight:600;flex-shrink:0}.current-member>div{min-width:0}.current-member strong{font-size:14px;line-height:1.6;font-weight:600;display:block;overflow-wrap:anywhere}.current-member>div>span{font-size:12px;line-height:1.8;color:var(--muted)}.member-role{margin-left:auto;font-size:12px;color:var(--muted);padding:5px 8px;background:var(--canvas);border-radius:4px;flex-shrink:0}.member-panel form{margin-top:24px}.member-panel h3{font-size:14px;font-weight:650;margin:0 0 8px}.form-description{font-size:14px;line-height:1.9;color:var(--muted);margin:0 0 21px}.member-panel label{display:block;margin:18px 0 8px;font-size:14px;font-weight:550;line-height:1.7}.member-panel input,.member-panel select{height:43px;padding:10px 12px;border:1px solid var(--line);border-radius:5px;background:var(--surface);color:var(--ink);width:100%;min-width:0;font-size:16px}.field-hint{display:block;font-size:12px;line-height:1.8;color:var(--muted);margin-top:6px}.create-member{display:flex;align-items:center;gap:22px;justify-content:space-between;margin-top:25px;font-size:14px;min-height:43px;padding:11px 15px}.member-success{display:flex;align-items:center;gap:7px;font-size:14px;line-height:1.8;color:var(--success);margin:18px 0 0}.member-permissions{display:flex;align-items:flex-start;gap:9px;font-size:14px;line-height:1.95;color:var(--muted);margin:21px 0 0}.member-permissions>svg{margin-top:3px;flex-shrink:0}
@media(max-width:1050px){.settings-view{gap:18px}.access-panel,.member-panel{padding:23px}}
@media(max-width:899px){.settings-view{grid-template-columns:minmax(0,1fr);max-width:700px}}
@media(max-width:479px){.access-panel,.member-panel{padding:20px}.settings-heading{gap:11px}.settings-heading h2{font-size:15px}.section-description{font-size:14px}.token-properties>div{grid-template-columns:70px minmax(0,1fr);gap:12px;font-size:14px}.token-result{padding:12px}.token-result-heading{gap:8px}.token-result-heading strong{font-size:14px}.member-panel select{font-size:16px}.token{font-size:14px}}
@media(max-width:767px){.member-panel input,.member-panel select{font-size:16px}}
</style>
